const GATE_AUDIO_RANDOM_BASE64 = "data:audio/mpeg;base64,";
const GATE_AUDIO_READY_BASE64 = "data:audio/mpeg;base64,";

let gateAudioCtx = null;
let gateRefTime = 0;
let gateCycleRunning = false;
let gateSequenceActive = false;
let gateAbortSequence = false;
let gateReactionDone = false;
let gateReactionMode = 'amarilla'; // 'roja' o 'amarilla'
let gateBeepsActive = true;
let gateHistoryByAthlete = {}; // { [athleteName]: [ { intentoNum, tiempo, modo, beeps, usuario, fechaHora } ] }

/**
 * Cambia entre las sub-pestañas de la vista Herramientas ('timer' | 'gate')
 */
function switchToolSubTab(subTab) {
    const subTimer = document.getElementById('toolSubViewTimer');
    const subGate = document.getElementById('toolSubViewGate');
    const btnTimer = document.getElementById('btnToolSubTimer');
    const btnGate = document.getElementById('btnToolSubGate');

    if (subTab === 'gate') {
        if (subTimer) subTimer.classList.add('hidden');
        if (subGate) subGate.classList.remove('hidden');
        if (btnGate) {
            btnGate.className = "flex-1 sm:flex-initial px-5 py-2.5 rounded-xl font-black text-xs sm:text-sm bg-gradient-to-r from-amber-500 to-red-600 text-white shadow-lg shadow-red-600/30 transition flex items-center justify-center gap-2 cursor-pointer";
        }
        if (btnTimer) {
            btnTimer.className = "flex-1 sm:flex-initial px-5 py-2.5 rounded-xl font-bold text-xs sm:text-sm bg-slate-800 text-slate-300 hover:text-white border border-slate-700 transition flex items-center justify-center gap-2 cursor-pointer";
        }
        syncGateAthleteUI();
    } else {
        if (gateCycleRunning) {
            gateAbortSequence = true;
            gateCycleRunning = false;
            gateSequenceActive = false;
        }
        if (subGate) subGate.classList.add('hidden');
        if (subTimer) subTimer.classList.remove('hidden');
        if (btnTimer) {
            btnTimer.className = "flex-1 sm:flex-initial px-5 py-2.5 rounded-xl font-black text-xs sm:text-sm bg-gradient-to-r from-red-600 to-amber-600 text-white shadow-lg shadow-red-600/30 transition flex items-center justify-center gap-2 cursor-pointer";
        }
        if (btnGate) {
            btnGate.className = "flex-1 sm:flex-initial px-5 py-2.5 rounded-xl font-bold text-xs sm:text-sm bg-slate-800 text-slate-300 hover:text-white border border-slate-700 transition flex items-center justify-center gap-2 cursor-pointer";
        }
    }
}

async function initGateAudioContext() {
    if (!gateAudioCtx) {
        const AudioContextClass = window.AudioContext || window.webkitAudioContext;
        gateAudioCtx = new AudioContextClass();
    }
    if (gateAudioCtx.state === 'suspended') {
        await gateAudioCtx.resume();
    }
}

function playGateVoiceBase64(base64Data, expectedDurationMs) {
    return new Promise(async (resolve) => {
        if (!base64Data || gateAbortSequence) {
            setTimeout(resolve, expectedDurationMs);
            return;
        }
        try {
            await initGateAudioContext();
            const res = await fetch(base64Data);
            const arrayBuffer = await res.arrayBuffer();
            const audioBuffer = await gateAudioCtx.decodeAudioData(arrayBuffer);

            if (gateAbortSequence) { resolve(); return; }

            const source = gateAudioCtx.createBufferSource();
            source.buffer = audioBuffer;
            source.connect(gateAudioCtx.destination);
            source.start(0);

            source.onended = () => resolve();
            setTimeout(() => resolve(), expectedDurationMs);
        } catch (e) {
            setTimeout(resolve, expectedDurationMs);
        }
    });
}

function playGateToneBeep(durationMs) {
    return new Promise(async (resolve) => {
        if (!gateBeepsActive || gateAbortSequence) {
            setTimeout(resolve, durationMs);
            return;
        }

        await initGateAudioContext();
        if (gateAbortSequence) { resolve(); return; }

        const osc = gateAudioCtx.createOscillator();
        const gain = gateAudioCtx.createGain();

        osc.type = 'sine';
        osc.frequency.setValueAtTime(632, gateAudioCtx.currentTime);

        osc.connect(gain);
        gain.connect(gateAudioCtx.destination);

        osc.start();
        setTimeout(() => {
            try { osc.stop(); } catch (e) {}
            resolve();
        }, durationMs);
    });
}

function resetGateLights() {
    ['gateLuzRoja', 'gateLuzAmarilla1', 'gateLuzAmarilla2', 'gateLuzVerde'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.classList.remove('activa');
    });
}

function setGateReactionMode(mode) {
    if (gateCycleRunning) return;
    gateReactionMode = mode;
    const btnRoja = document.getElementById('btnGateModoRoja');
    const btnAmarilla = document.getElementById('btnGateModoAmarilla');
    if (btnRoja && btnAmarilla) {
        if (mode === 'roja') {
            btnRoja.className = "flex-1 py-2.5 px-3 rounded-xl font-black text-xs bg-amber-400 text-slate-950 border border-amber-400 shadow transition cursor-pointer";
            btnAmarilla.className = "flex-1 py-2.5 px-3 rounded-xl font-bold text-xs bg-slate-900 text-slate-400 border border-slate-700 hover:text-white transition cursor-pointer";
        } else {
            btnAmarilla.className = "flex-1 py-2.5 px-3 rounded-xl font-black text-xs bg-amber-400 text-slate-950 border border-amber-400 shadow transition cursor-pointer";
            btnRoja.className = "flex-1 py-2.5 px-3 rounded-xl font-bold text-xs bg-slate-900 text-slate-400 border border-slate-700 hover:text-white transition cursor-pointer";
        }
    }
}

function toggleGateFrequencyBeeps() {
    if (gateCycleRunning) return;
    gateBeepsActive = !gateBeepsActive;
    const btn = document.getElementById('btnGateBeepToggle');
    if (btn) {
        if (gateBeepsActive) {
            btn.innerHTML = '<i class="fa-solid fa-volume-high mr-1.5"></i> Beeps de Frecuencia: ACTIVOS';
            btn.className = "w-full py-2.5 px-4 rounded-xl font-bold text-xs bg-emerald-950/50 text-emerald-400 border border-emerald-500/50 hover:bg-emerald-900/40 transition cursor-pointer";
        } else {
            btn.innerHTML = '<i class="fa-solid fa-volume-xmark mr-1.5"></i> Beeps de Frecuencia: SILENCIADOS';
            btn.className = "w-full py-2.5 px-4 rounded-xl font-bold text-xs bg-slate-800 text-amber-400 border border-slate-700 hover:bg-slate-700 transition cursor-pointer";
        }
    }
}

async function startGateSequence() {
    if (gateCycleRunning) return;
    gateCycleRunning = true;
    gateSequenceActive = false;
    gateAbortSequence = false;
    gateReactionDone = false;

    const btnIniciar = document.getElementById('btnGateIniciar');
    const btnReaccion = document.getElementById('btnGateReaccion');
    const txtMensaje = document.getElementById('txtGateMensaje');
    const txtTiempo = document.getElementById('txtGateTiempo');
    const btnModoRoja = document.getElementById('btnGateModoRoja');
    const btnModoAmarilla = document.getElementById('btnGateModoAmarilla');
    const btnBeepToggle = document.getElementById('btnGateBeepToggle');

    if (btnReaccion) {
        btnReaccion.style.backgroundColor = '#00cc44';
    }
    if (txtTiempo) txtTiempo.textContent = "";

    if (btnIniciar) {
        btnIniciar.disabled = true;
        btnIniciar.style.opacity = '0.5';
    }
    if (btnModoRoja) btnModoRoja.style.opacity = '0.5';
    if (btnModoAmarilla) btnModoAmarilla.style.opacity = '0.5';
    if (btnBeepToggle) btnBeepToggle.style.opacity = '0.5';

    resetGateLights();

    try {
        if (txtMensaje) txtMensaje.textContent = "OK riders, random start";
        await playGateVoiceBase64(GATE_AUDIO_RANDOM_BASE64, 1500);
        if (gateAbortSequence) return;

        await new Promise(r => setTimeout(r, 1800));
        if (gateAbortSequence) return;

        if (txtMensaje) txtMensaje.textContent = "Riders ready, watch the gate";
        await playGateVoiceBase64(GATE_AUDIO_READY_BASE64, 2000);
        if (gateAbortSequence) return;

        const randomPause = Math.random() * (2700 - 100) + 100;
        await new Promise(r => setTimeout(r, randomPause));
        if (gateAbortSequence) return;

        gateSequenceActive = true;
        if (txtMensaje) txtMensaje.textContent = "¡CAÍDA DE PARTIDOR! (GATE DROP!)";

        const luzRoja = document.getElementById('gateLuzRoja');
        const luzAmarilla1 = document.getElementById('gateLuzAmarilla1');
        const luzAmarilla2 = document.getElementById('gateLuzAmarilla2');
        const luzVerde = document.getElementById('gateLuzVerde');

        if (luzRoja) luzRoja.classList.add('activa');
        if (gateReactionMode === 'roja') {
            gateRefTime = performance.now();
        }
        await playGateToneBeep(60);
        if (gateAbortSequence) return;

        await new Promise(r => setTimeout(r, 60));
        if (gateAbortSequence) return;

        if (luzAmarilla1) luzAmarilla1.classList.add('activa');
        if (gateReactionMode === 'amarilla') {
            gateRefTime = performance.now();
        }
        await playGateToneBeep(60);
        if (gateAbortSequence) return;

        await new Promise(r => setTimeout(r, 60));
        if (gateAbortSequence) return;

        if (luzAmarilla2) luzAmarilla2.classList.add('activa');
        await playGateToneBeep(60);
        if (gateAbortSequence) return;

        await new Promise(r => setTimeout(r, 60));
        if (gateAbortSequence) return;

        if (luzVerde) luzVerde.classList.add('activa');
        await playGateToneBeep(2250);
    } catch (e) {
        console.error(e);
    } finally {
        gateCycleRunning = false;
        gateSequenceActive = false;
        if (btnIniciar) {
            btnIniciar.disabled = false;
            btnIniciar.style.opacity = '1';
        }
        if (btnModoRoja) btnModoRoja.style.opacity = '1';
        if (btnModoAmarilla) btnModoAmarilla.style.opacity = '1';
        if (btnBeepToggle) btnBeepToggle.style.opacity = '1';
    }
}

function getActiveGateAthlete() {
    return (typeof state !== 'undefined' && state.currentAthlete) ? state.currentAthlete : 'Piloto';
}

function getAthleteGateAttempts() {
    const athlete = getActiveGateAthlete();
    if (!gateHistoryByAthlete[athlete]) {
        gateHistoryByAthlete[athlete] = [];
    }
    return gateHistoryByAthlete[athlete];
}

function recordGateReaction() {
    if (gateReactionDone) return;

    const endTime = performance.now();
    const btnReaccion = document.getElementById('btnGateReaccion');
    const btnIniciar = document.getElementById('btnGateIniciar');
    const txtMensaje = document.getElementById('txtGateMensaje');
    const txtTiempo = document.getElementById('txtGateTiempo');
    const btnModoRoja = document.getElementById('btnGateModoRoja');
    const btnModoAmarilla = document.getElementById('btnGateModoAmarilla');
    const btnBeepToggle = document.getElementById('btnGateBeepToggle');

    const athlete = getActiveGateAthlete();
    const list = getAthleteGateAttempts();

    if (!gateSequenceActive) {
        gateReactionDone = true;
        gateAbortSequence = true;
        gateCycleRunning = false;

        if (btnReaccion) btnReaccion.style.backgroundColor = '#ff3333';
        if (btnIniciar) {
            btnIniciar.disabled = false;
            btnIniciar.style.opacity = '1';
        }
        if (btnModoRoja) btnModoRoja.style.opacity = '1';
        if (btnModoAmarilla) btnModoAmarilla.style.opacity = '1';
        if (btnBeepToggle) btnBeepToggle.style.opacity = '1';

        if (txtMensaje) txtMensaje.textContent = "¡Salida en falso! Reinicia la secuencia";
        if (txtTiempo) {
            txtTiempo.textContent = "FALLO";
            txtTiempo.style.color = "#ff3333";
        }

        list.unshift({
            intentoNum: list.length + 1,
            tiempo: 1000,
            modo: gateReactionMode,
            beeps: gateBeepsActive,
            usuario: athlete,
            fechaHora: formatGateDateTime(new Date())
        });
        saveGateHistoryToStorage();
        updateGateTableUI();
        return;
    }

    gateReactionDone = true;
    const diffMs = Math.round(endTime - gateRefTime);

    if (btnReaccion) btnReaccion.style.backgroundColor = '#00a8ff';

    if (txtMensaje) {
        if (diffMs >= 0 && diffMs <= 100) {
            txtMensaje.textContent = "¡Excelente salida! Máxima potencia ⚡";
        } else if (diffMs >= 101 && diffMs <= 200) {
            txtMensaje.textContent = "Buena reacción, sigue afinando el reflejo";
        } else {
            txtMensaje.textContent = "Reacción lenta, practica más en el partidor";
        }
    }

    if (txtTiempo) {
        txtTiempo.textContent = `${diffMs} ms`;
        txtTiempo.style.color = "#00a8ff";
    }

    list.unshift({
        intentoNum: list.length + 1,
        tiempo: diffMs,
        modo: gateReactionMode,
        beeps: gateBeepsActive,
        usuario: athlete,
        fechaHora: formatGateDateTime(new Date())
    });
    saveGateHistoryToStorage();
    updateGateTableUI();
}

function formatGateDateTime(date) {
    const d = date || new Date();
    const dia = String(d.getDate()).padStart(2, '0');
    const mes = String(d.getMonth() + 1).padStart(2, '0');
    const hora = String(d.getHours()).padStart(2, '0');
    const min = String(d.getMinutes()).padStart(2, '0');
    return `${dia}/${mes} ${hora}:${min}`;
}

function updateGateTableUI() {
    const tbody = document.getElementById('tablaGateIntentos');
    const txtPromedio = document.getElementById('txtGatePromedio');
    const txtMejor = document.getElementById('txtGateMejor');
    const txtFallos = document.getElementById('txtGateFallos');
    if (!tbody) return;

    const list = getAthleteGateAttempts();
    tbody.innerHTML = "";

    if (list.length === 0) {
        tbody.innerHTML = `<tr><td colspan="3" class="py-6 text-slate-500 text-xs">Aún no hay intentos registrados para este piloto</td></tr>`;
        if (txtPromedio) txtPromedio.textContent = "--- ms";
        if (txtMejor) txtMejor.textContent = "--- ms";
        if (txtFallos) txtFallos.textContent = "0";
        return;
    }

    let suma = 0;
    let mejor = Infinity;
    let fallos = 0;
    let validosCount = 0;

    list.forEach(item => {
        const val = (typeof item === 'object') ? item.tiempo : item;
        if (val === 1000 || val === 'FAIL' || val === 'FALLO') {
            fallos++;
        } else {
            if (val < mejor) mejor = val;
            suma += val;
            validosCount++;
        }
    });

    list.forEach((item, index) => {
        const fila = document.createElement('tr');
        fila.className = "border-b border-slate-800/80 hover:bg-slate-800/40 transition";
        const val = (typeof item === 'object') ? item.tiempo : item;
        const isFail = (val === 1000 || val === 'FAIL' || val === 'FALLO');
        const textoTiempo = isFail
            ? '<span class="text-red-400 font-black">FALLO</span>'
            : `<span class="text-cyan-400 font-bold">${val} ms</span>`;
        const fechaTexto = (typeof item === 'object' && item.fechaHora) ? item.fechaHora : '---';
        const numIntento = list.length - index;
        fila.innerHTML = `
            <td class="py-2 px-3 text-xs font-mono text-slate-300">#${numIntento}</td>
            <td class="py-2 px-3 text-xs font-mono">${textoTiempo}</td>
            <td class="py-2 px-3 text-[11px] text-slate-400">${fechaTexto}</td>
        `;
        tbody.appendChild(fila);
    });

    const promedio = validosCount > 0 ? Math.round(suma / validosCount) : 0;
    if (txtPromedio) txtPromedio.textContent = validosCount > 0 ? `${promedio} ms` : "--- ms";
    if (txtMejor) txtMejor.textContent = (mejor !== Infinity) ? `${mejor} ms` : "--- ms";
    if (txtFallos) txtFallos.textContent = String(fallos);
}

function saveGateHistoryToStorage() {
    try {
        localStorage.setItem('activerza_bmx_gate_history_v1', JSON.stringify(gateHistoryByAthlete));
    } catch (e) {
        console.error('Error guardando historial de partidor:', e);
    }
}

function loadGateHistoryFromStorage() {
    try {
        const raw = localStorage.getItem('activerza_bmx_gate_history_v1');
        if (raw) {
            const parsed = JSON.parse(raw);
            if (parsed && typeof parsed === 'object') {
                gateHistoryByAthlete = parsed;
            }
        } else {
            // Migrar historial previo si existía en bmx_historial_intentos
            const legacy = localStorage.getItem('bmx_historial_intentos');
            if (legacy) {
                const parsedLegacy = JSON.parse(legacy);
                if (Array.isArray(parsedLegacy) && parsedLegacy.length > 0) {
                    gateHistoryByAthlete[getActiveGateAthlete()] = parsedLegacy;
                }
            }
        }
    } catch (e) {
        console.error('Error cargando historial de partidor:', e);
    }
}

function syncGateAthleteUI() {
    const lbl = document.getElementById('lblGateNombrePiloto');
    if (lbl) lbl.textContent = getActiveGateAthlete();
    updateGateTableUI();
}

async function exportGateHistoryFile() {
    const athlete = getActiveGateAthlete();
    const list = getAthleteGateAttempts();
    if (list.length === 0) {
        alert("¡No hay historial de intentos para exportar!");
        return;
    }

    const datosExportar = {
        app: "BMX Gate Start Pro Practice - ACTIVERZA",
        usuario: athlete,
        fechaExportacion: new Date().toISOString(),
        totalIntentos: list.length,
        historial: list
    };

    const fileName = `bmx_gate_${athlete.toLowerCase().replace(/\s+/g, '_')}_${Date.now()}.json`;
    const blob = new Blob([JSON.stringify(datosExportar, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}

function importGateHistoryFile(event) {
    const file = event.target.files && event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
        try {
            const json = JSON.parse(evt.target.result);
            const athlete = getActiveGateAthlete();
            if (json && Array.isArray(json.historial)) {
                gateHistoryByAthlete[athlete] = json.historial;
                saveGateHistoryToStorage();
                updateGateTableUI();
                alert(`¡Historial cargado con éxito para ${athlete}! (${json.historial.length} intentos)`);
            } else if (Array.isArray(json)) {
                gateHistoryByAthlete[athlete] = json;
                saveGateHistoryToStorage();
                updateGateTableUI();
                alert(`¡Historial cargado con éxito! (${json.length} intentos)`);
            } else {
                alert("Formato de archivo inválido.");
            }
        } catch (err) {
            alert("Error al leer el archivo JSON.");
        }
    };
    reader.readAsText(file);
    event.target.value = "";
}

function clearGateHistory() {
    const athlete = getActiveGateAthlete();
    if (confirm(`¿Estás seguro de borrar el historial de partidor de ${athlete}?`)) {
        gateHistoryByAthlete[athlete] = [];
        saveGateHistoryToStorage();
        updateGateTableUI();
    }
}

document.addEventListener('DOMContentLoaded', () => {
    loadGateHistoryFromStorage();
    syncGateAthleteUI();
    const btnReaccion = document.getElementById('btnGateReaccion');
    if (btnReaccion) {
        btnReaccion.addEventListener('touchstart', (e) => {
            e.preventDefault();
            recordGateReaction();
        }, { passive: false });
    }
});
